class UnbalancedLedgerError(Exception):
    """Raised when the sum of debits does not equal the sum of credits in a transaction."""
    pass


class DuplicateTransactionError(Exception):
    """Raised when an idempotency key is reused for a different transaction payload."""
    pass


class InvalidAmountError(Exception):
    """Raised when a transaction amount is negative or zero."""
    pass


class AccountLockedError(Exception):
    """Raised when an account lock cannot be acquired."""
