    def check_idempotency(self, idempotency_key: str, transaction_hash: str) -> bool:
        """Returns True if key exists with matching hash, raises DuplicateTransactionError if mismatch."""
        ...

    def record_transaction(
        self,
        idempotency_key: str,
        transaction_hash: str,
        entries: List["LedgerEntry"]
    ) -> None:
        ...


